'use strict';
const $=s=>document.querySelector(s), app=$('#app'), KEY='life-sprint-214-v1';
const RANKS=[['Rookie',0],['Bronze',150],['Silver',400],['Gold',850],['Platinum',1400],['Diamond',2200]];
let state={xp:0,stats:{},sessions:[],active:null}, storageOK=true,view='home',lessonTopic=0,toastTimer;
try{const saved=JSON.parse(localStorage.getItem(KEY));if(saved&&saved.stats&&Array.isArray(saved.sessions))state={...state,...saved};}catch(e){storageOK=false;}
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const shuffle=a=>{a=[...a];for(let i=a.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]];}return a;};
const byId=id=>BANK.find(q=>q.id===id);
const misses=()=>BANK.filter(q=>state.stats[q.id]?.missed);
const rank=()=>RANKS.reduce((a,r)=>state.xp>=r[1]?r:a,RANKS[0]);
function save(){try{localStorage.setItem(KEY,JSON.stringify(state));}catch(e){storageOK=false;}chrome();}
function toast(s){clearTimeout(toastTimer);$('#toast').textContent=s;$('#toast').style.display='block';toastTimer=setTimeout(()=>$('#toast').style.display='none',3200);}
function chrome(){const r=rank(),next=RANKS[RANKS.indexOf(r)+1],percent=next?Math.max(0,Math.min(100,(state.xp-r[1])/(next[1]-r[1])*100)):100;$('#rank').innerHTML=`<div class="eyebrow">PRACTICE RANK</div><div class="rank-icon">◇</div><h3>${r[0]}</h3><div class="track"><i style="width:${percent}%"></i></div><div class="small muted">${state.xp} XP ${next?`· ${next[1]-state.xp} to ${next[0]}`:'· Top rank'}</div>`;$('#missBadge').textContent=misses().length||'';$('#saveNote').innerHTML=storageOK?'Progress saves on this browser.<br>No account needed.':'Storage unavailable. Keep this page open; progress may be lost.';document.querySelectorAll('nav button').forEach(b=>b.classList.toggle('active',b.dataset.view===view));}
function stats(t){const qs=t===undefined?BANK:BANK.filter(q=>q.t===t);let n=0,c=0,seen=0;qs.forEach(q=>{const s=state.stats[q.id];if(s){n+=s.n;c+=s.c;seen++;}});return {n,c,seen,pct:n?Math.round(c/n*100):null};}
function go(v){view=v;chrome();if(v==='home')home();if(v==='learn')learn();if(v==='mistakes')mistakeView();if(v==='progress')progress();if(v==='sources')sources();if(v==='quiz')quiz();window.scrollTo(0,0);}
function home(){const s=stats();app.innerHTML=`<div class="topline"><div><div class="eyebrow">ONE QUESTION CLOSER</div><h1>Make the concepts click.</h1><p class="muted">Florida life, annuities & variable contracts.</p></div><span class="pill">${rank()[0]} · ${state.xp} XP</span></div><div class="stats"><div class="stat"><strong>${s.seen}<span> / ${BANK.length}</span></strong><span>Questions explored</span></div><div class="stat"><strong>${s.pct===null?'—':s.pct+'%'}</strong><span>Practice accuracy</span></div><div class="stat"><strong>${misses().length}</strong><span>To revisit</span></div></div>${state.active?`<div class="notice">You have an unfinished ${modeName(state.active.mode)} session. Timers continue while away.<div class="actions"><button class="btn" data-action="resume">Resume session</button><button class="btn secondary" data-action="discard">Discard session</button></div></div>`:''}<section class="hero"><div><div class="eyebrow">START HERE · 15 QUESTIONS</div><h2>Find your weak spots.<br>Turn them into points.</h2><p>Short, mixed practice. Simple explanations after every answer. No timer, no pressure.</p><button class="btn dark" data-start="practice">Start a training round ↗</button></div><div class="big-number" aria-hidden="true">2<br>14</div></section><div class="grid3"><section class="card mode"><div class="icon">◷</div><h3>5-minute sprint</h3><p>Race the clock through 20 questions. Accuracy comes first; +15 XP per correct answer.</p><button class="btn secondary" data-start="sprint">Take the challenge</button></section><section class="card mode"><div class="icon">▤</div><h3>Exam rehearsal</h3><p>95 questions. Two hours. Review answers at the end. Aim for 85%+ as a study target.</p><button class="btn secondary" data-start="mock">Start practice exam</button></section><section class="card mode"><div class="icon">↻</div><h3>Mistake lab</h3><p>Revisit missed concepts until you can explain why the answer is right.</p><button class="btn secondary" data-view="mistakes">Review ${misses().length} missed</button></section></div><div class="sectiontitle"><h2>Pick a topic to train</h2><span class="small muted">Percent = share of official outline</span></div><div class="topics">${TOPICS.map((t,i)=>`<button class="topic" data-topic="${i}"><span class="num">0${i+1}</span><span><b>${t[0]}</b><small>${stats(i).seen} of ${BANK.filter(q=>q.t===i).length} explored</small></span><span class="weight">${t[1]}%</span></button>`).join('')}</div><div class="notice"><b>Tonight's route:</b> Mixed round → quick lessons for weak topics → mistake lab → one exam rehearsal. Use the sprint for recall, then leave time to sleep. This app is a focused practice aid, not a score guarantee or a replacement for your course.</div>`;}
function modeName(m){return ({practice:'training',sprint:'5-minute sprint',mock:'exam rehearsal',review:'mistake review',topic:'topic drill'})[m]||m;}
function weighted(counts){return shuffle(counts.flatMap((n,t)=>shuffle(BANK.filter(q=>q.t===t)).slice(0,n)));}
function start(mode,t){if(state.active){toast('Resume or discard your unfinished session first.');go('home');return;}let qs;if(mode==='mock')qs=weighted([17,17,13,9,23,16]);else if(mode==='review')qs=shuffle(misses()).slice(0,20);else if(mode==='topic')qs=shuffle(BANK.filter(q=>q.t===t)).slice(0,15);else if(mode==='sprint')qs=weighted([4,3,3,2,5,3]);else qs=weighted([3,3,2,1,3,3]);if(!qs.length){toast('No missed questions yet. Try a training round.');return;}const seconds=mode==='mock'?7200:mode==='sprint'?300:0;state.active={mode,ids:qs.map(q=>q.id),orders:qs.map(()=>shuffle([0,1,2,3])),answers:qs.map(()=>null),flags:[],index:0,start:Date.now(),deadline:seconds?Date.now()+seconds*1000:null,recorded:[],xpStart:state.xp};save();go('quiz');}
function record(q,choice,m){const previousRank=rank()[0];const s=state.stats[q.id]||{n:0,c:0,missed:false};s.n++;const correct=choice===0;if(correct){s.c++;s.missed=false;state.xp+=(m==='sprint'?15:10);}else s.missed=true;state.stats[q.id]=s;if(rank()[0]!==previousRank)toast(`Rank up! You're now ${rank()[0]}.`);}
function quiz(){const a=state.active;if(!a){go('home');return;}if(a.deadline&&Date.now()>=a.deadline){finish(true);return;}const i=a.index,q=byId(a.ids[i]),selected=a.answers[i],locked=a.mode!=='mock'&&selected!==null;app.innerHTML=`<div class="question"><div class="topline"><span class="pill">${modeName(a.mode)}</span><span id="clock" class="clock"></span></div><div class="track"><i style="width:${(i+1)/a.ids.length*100}%"></i></div><div class="topline small muted"><span>Question ${i+1} of ${a.ids.length}</span><span>${TOPICS[q.t][0]}</span></div><h1 class="qtitle">${esc(q.q)}</h1><div class="answers">${a.orders[i].map((opt,pos)=>`<button class="answer ${selected===opt?'selected':''} ${locked&&opt===0?'correct':''} ${locked&&selected===opt&&opt!==0?'wrong':''}" data-answer="${opt}" ${locked?'disabled':''}><span class="letter">${'ABCD'[pos]}</span><span>${esc(q.options[opt])}${locked&&opt===0?' ✓':''}</span></button>`).join('')}</div>${locked?`<div class="feedback ${selected===0?'':'bad'}" role="status"><h3>${selected===0?`Correct · +${a.mode==='sprint'?15:10} XP`:'Not quite. Here’s the idea.'}</h3>${selected!==0?`<p><b>${esc(q.options[0])}</b></p>`:''}<p>${esc(q.why)}</p></div>`:''}<div class="actions">${a.mode==='mock'?`<button class="btn secondary" data-action="prev" ${i===0?'disabled':''}>Back</button><button class="btn secondary" data-action="flag">${a.flags.includes(i)?'★ Flagged':'☆ Flag'}</button>`:''}<button class="btn secondary" data-view="home">Save & leave</button><span class="spacer"></span><button class="btn" data-action="next" ${a.mode!=='mock'&&!locked?'disabled':''}>${i===a.ids.length-1?(a.mode==='mock'?'Review & submit':'Finish round'):'Next question →'}</button></div>${a.mode==='mock'?`<div class="qnav" aria-label="Question navigation">${a.ids.map((id,j)=>`<button data-jump="${j}" aria-label="Question ${j+1}${a.answers[j]!==null?', answered':''}${a.flags.includes(j)?', flagged':''}" class="${a.answers[j]!==null?'done':''} ${j===i?'current':''} ${a.flags.includes(j)?'flagged':''}">${j+1}</button>`).join('')}</div><button class="btn secondary" data-action="submit">Review & submit exam</button><p class="small muted">Answers can be changed until submission. Explanations appear after submission.</p>`:`<p class="small muted">One attempt per question in this round. Missed answers go to your mistake lab.</p>`}</div>`;tick();}
function tick(){const a=state.active;if(!a)return;if(a.deadline&&Date.now()>=a.deadline){finish(true);return;}const el=$('#clock');if(!el)return;if(!a.deadline){el.textContent='Untimed';return;}const sec=Math.max(0,Math.ceil((a.deadline-Date.now())/1000));el.textContent=`${Math.floor(sec/60)}:${String(sec%60).padStart(2,'0')}`;el.classList.toggle('urgent',sec<=60);}
function submitView(){const a=state.active;if(!a)return;const n=a.answers.filter(x=>x===null).length;app.innerHTML=`<div class="card"><div class="eyebrow">FINAL CHECK</div><h1>Ready to score?</h1><p>${a.ids.length-n} of ${a.ids.length} answered. ${n} unanswered. ${a.flags.length} flagged.</p><p class="muted">Unanswered questions count as incorrect. All 95 practice questions are scored here; the real exam has 85 scored and 10 unscored questions.</p><div class="actions"><button class="btn secondary" data-action="resume">Return to questions</button><button class="btn" data-action="finish">Submit answers</button></div></div>`;}
function finish(expired=false){const a=state.active;if(!a)return;const before=a.xpStart; a.ids.forEach((id,i)=>{if(!a.recorded.includes(i)&&(a.answers[i]!==null||a.mode==='mock'))record(byId(id),a.answers[i],a.mode);});const result={mode:a.mode,ids:a.ids,answers:a.answers,date:new Date().toISOString(),correct:a.answers.filter(v=>v===0).length,total:a.mode==='sprint'?a.answers.filter(v=>v!==null).length:a.ids.length,available:a.ids.length,xp:state.xp-before,expired};state.sessions.unshift(result);state.sessions=state.sessions.slice(0,20);state.active=null;save();view='result';chrome();results(result);window.scrollTo(0,0);}
function results(r){const pct=r.total?Math.round(r.correct/r.total*100):0;app.innerHTML=`<div class="eyebrow">${r.expired?'TIME IS UP':'ROUND COMPLETE'} · ${modeName(r.mode)}</div><h1>${pct>=85?'Strong round. Keep it consistent.':pct>=70?'Good progress. Close the gaps.':'You found what to work on.'}</h1><div class="card"><div class="topline"><div><div class="resultscore">${pct}%</div><p>${r.correct} / ${r.total} correct${r.mode==='sprint'?` · ${r.total} of ${r.available} attempted`:''}</p></div><span class="pill">+${r.xp} XP · ${rank()[0]}</span></div><p class="muted">${r.mode==='mock'?'Aim for repeated 85%+ practice scores as a buffer. This is a study target, not a prediction of your licensing score.':'Read the explanation for anything you missed, then test yourself again.'}</p><div class="actions"><button class="btn" data-start="review" ${misses().length?'':'disabled'}>Train missed questions</button><button class="btn secondary" data-view="home">Back to training</button></div></div><div class="sectiontitle"><h2>Answer review</h2><span class="small muted">${r.mode==='mock'?'All questions':'Your round'}</span></div>${r.ids.map((id,i)=>{const q=byId(id),a=r.answers[i];return `<div class="reviewitem"><h3>${i+1}. ${esc(q.q)}</h3><p class="${a===0?'righttext':'wrongtext'}">${a===null?'Not answered':`Your answer: ${esc(q.options[a])}`}${a===0?' ✓':''}</p>${a!==0?`<p class="righttext">Correct: ${esc(q.options[0])}</p>`:''}<p class="muted">${esc(q.why)}</p></div>`;}).join('')}`;}
function learn(){app.innerHTML=`<div class="eyebrow">UNDERSTAND FIRST. MEMORIZE LESS.</div><h1>Quick lessons</h1><p class="muted">Open a question to see the answer and a simple explanation.</p><label for="lessonSelect" class="small">Choose a topic</label><br><select id="lessonSelect">${TOPICS.map((t,i)=>`<option value="${i}" ${i===lessonTopic?'selected':''}>${t[0]} · ${t[1]}%</option>`).join('')}</select><section class="card lesson"><div class="lessonhead"><h2>${TOPICS[lessonTopic][0]}</h2><p class="muted">${TOPICS[lessonTopic][2]}</p><button class="btn" data-topic="${lessonTopic}">Quiz me on this topic</button></div>${BANK.filter(q=>q.t===lessonTopic).map(q=>`<details><summary>${esc(q.q)}</summary><p><b>${esc(q.options[0])}.</b> ${esc(q.why)}</p></details>`).join('')}</section>`;$('#lessonSelect').onchange=e=>{lessonTopic=Number(e.target.value);learn();};}
function mistakeView(){const m=misses();app.innerHTML=`<div class="eyebrow">MISTAKES ARE YOUR STUDY PLAN</div><h1>Mistake lab <span class="muted">/ ${m.length}</span></h1><p class="muted">A correct answer in a later drill clears that question from this list.</p><button class="btn" data-start="review" ${m.length?'':'disabled'}>Train ${Math.min(m.length,20)} missed questions</button>${m.length?m.map(q=>`<div class="reviewitem"><span class="pill">${TOPICS[q.t][0]}</span><h3 style="margin-top:14px">${esc(q.q)}</h3><p class="righttext">${esc(q.options[0])}</p><p class="muted">${esc(q.why)}</p></div>`).join(''):'<div class="notice">Nothing to revisit yet. Start a training round to find your weak spots.</div>'}`;}
function progress(){app.innerHTML=`<div class="eyebrow">EFFORT EARNS RANK. ACCURACY SHOWS LEARNING.</div><h1>Your progress</h1><div class="card"><div class="topline"><h2>${rank()[0]}</h2><span class="pill">${state.xp} XP</span></div><p class="muted">Correct answer: 10 XP. Sprint: 15 XP. No XP lost for a mistake. Ranks measure practice, not exam readiness.</p><div class="roadmap">${RANKS.map(r=>`<span class="${state.xp>=r[1]?'unlocked':''}">${r[0]} · ${r[1]}</span>`).join('')}</div></div><div class="sectiontitle"><h2>Where to focus next</h2></div>${TOPICS.map((t,i)=>{const s=stats(i);return `<div class="reviewitem"><div class="topline"><b>${t[0]}</b><span>${s.pct===null?'Unseen':s.pct+'%'}</span></div><div class="track"><i style="width:${s.pct||0}%"></i></div><span class="small muted">${s.n} answers · ${s.seen} unique questions seen</span></div>`;}).join('')}<div class="sectiontitle"><h2>Recent rounds</h2></div>${state.sessions.length?state.sessions.map((r,i)=>`<button class="topic" data-result="${i}" style="width:100%;margin-bottom:10px"><span><b>${modeName(r.mode)}</b><small>${new Date(r.date).toLocaleDateString()} · ${r.correct}/${r.total} correct</small></span><span class="weight">${r.total?Math.round(r.correct/r.total*100):0}%</span></button>`).join(''):'<p class="muted">Finish a round to see your results here.</p>'}`;}
function sources(){app.innerHTML=`<div class="eyebrow">FLORIDA 2–14 · LIFE ONLY</div><h1>Know the exam</h1><div class="card"><h2>95 questions · 2 hours</h2><p>The official 2026 outline lists 85 scored questions plus 10 unscored pretest questions. You won't know which are unscored. Answer every question. The published passing score is 70%; 85%+ is our higher practice target.</p><p class="muted">Our rehearsal uses 95 original practice questions with approximately the outline's topic proportions. All are scored for feedback here. This is not an official exam or a complete course.</p><table><thead><tr><th>Section</th><th>Weight</th></tr></thead><tbody>${TOPICS.map(t=>`<tr><td>${t[0]}</td><td>${t[1]}%</td></tr>`).join('')}</tbody></table></div><div class="sectiontitle"><h2>Numbers worth separating</h2></div><div class="card"><p><b>14 days:</b> ordinary nonreplacement life free look after delivery.</p><p><b>21 days:</b> annuity free look.</p><p><b>At least 30 days:</b> individual life premium grace period after the first premium.</p><p><b>31 days:</b> eligible group life conversion application and first premium.</p><p><b>Within 3 years:</b> life reinstatement after premium default, subject to conditions.</p><p class="small muted">Read the question's context. Special contracts and replacement situations can have additional rules.</p></div><div class="sectiontitle"><h2>Official references</h2></div><p class="muted small">Checked September 27, 2026. Questions and explanations are original study material. Use your course for topics and details beyond this focused bank.</p><ul class="sources"><li><a target="_blank" rel="noopener" href="https://www.pearsonvue.com/content/dam/VUE/vue/en/documents/publications/121003.pdf">Pearson VUE · 2026 Florida content outline (first 3 pages)</a></li><li><a target="_blank" rel="noopener" href="https://www.pearsonvue.com/content/dam/VUE/vue/en/documents/publications/121000.pdf">Pearson VUE · Candidate handbook and test-day rules</a></li><li><a target="_blank" rel="noopener" href="https://www.myfloridacfo.com/division/consumers/understanding-insurance/lifeinsuranceoverview">Florida DFS · Life insurance overview</a></li><li><a target="_blank" rel="noopener" href="https://myfloridacfo.com/division/consumers/understanding-insurance/annuityoverview">Florida DFS · Annuity overview</a></li><li><a target="_blank" rel="noopener" href="https://content.naic.org/insurance-topics/life-insurance">NAIC · Life insurance</a></li>${['627.453','627.455','627.459','627.566','627.4554','626.9541','626.572','626.551','626.431'].map(s=>`<li><a target="_blank" rel="noopener" href="https://www.flsenate.gov/Laws/Statutes/2026/${s}">Florida Statutes § ${s}</a></li>`).join('')}</ul><div class="notice">Before test day: confirm your appointment time, location, identification requirements, and check-in instructions in your booking and candidate handbook. Practice scores do not guarantee a licensing result.</div>`;}
document.addEventListener('click',e=>{const b=e.target.closest('button,a.brand');if(!b||b.disabled)return;if(b.matches('a.brand')){e.preventDefault();go('home');return;}if(b.dataset.view){go(b.dataset.view);return;}if(b.dataset.start){start(b.dataset.start);return;}if(b.dataset.topic!==undefined){start('topic',Number(b.dataset.topic));return;}if(b.dataset.result!==undefined){view='result';results(state.sessions[Number(b.dataset.result)]);window.scrollTo(0,0);return;}const a=state.active;if(b.dataset.answer!==undefined&&a){if(a.deadline&&Date.now()>=a.deadline){finish(true);return;}const i=a.index;if(a.mode!=='mock'&&a.answers[i]!==null)return;a.answers[i]=Number(b.dataset.answer);if(a.mode!=='mock'){record(byId(a.ids[i]),a.answers[i],a.mode);a.recorded.push(i);}save();quiz();return;}if(b.dataset.jump!==undefined&&a){a.index=Number(b.dataset.jump);save();quiz();return;}switch(b.dataset.action){case 'resume':go('quiz');break;case 'discard':if(confirm('Discard this unfinished session? Completed training answers and earned XP stay saved.')){state.active=null;save();go('home');}break;case 'next':if(!a)return;if(a.index<a.ids.length-1){a.index++;save();quiz();window.scrollTo(0,0);}else if(a.mode==='mock')submitView();else finish();break;case 'prev':if(a&&a.index>0){a.index--;save();quiz();}break;case 'flag':if(a){const j=a.flags.indexOf(a.index);if(j>=0)a.flags.splice(j,1);else a.flags.push(a.index);save();quiz();}break;case 'submit':submitView();break;case 'finish':finish();break;}});
setInterval(tick,500);document.addEventListener('visibilitychange',tick);go('home');
